package com.bank.food;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

enum OrderStatus {
    PLACED, ACCEPTED, PREPARING, OUT_FOR_DELIVERY, DELIVERED, CANCELLED;
    boolean canGoTo(OrderStatus next) {
        return switch (this) {
            case PLACED -> next == ACCEPTED || next == CANCELLED;
            case ACCEPTED -> next == PREPARING || next == CANCELLED;
            case PREPARING -> next == OUT_FOR_DELIVERY;
            case OUT_FOR_DELIVERY -> next == DELIVERED;
            default -> false;
        };
    }
}

class MenuItem {
    final String name; final BigDecimal price;
        MenuItem(String name, BigDecimal price) { this.name = name;
        this.price = price; }
}

interface OrderObserver { void onStatusChange(Order o); }

class Order {
    private static final Logger log = Logger.getLogger("FOOD");
        final String id, user, restaurant;
        OrderStatus status = OrderStatus.PLACED;
    final List<MenuItem> items = new ArrayList<>();
    private final List<OrderObserver> observers = new ArrayList<>();
        Order(String id, String user, String restaurant) { this.id = id;
        this.user = user
        this.restaurant = restaurant; }
    void subscribe(OrderObserver o) { observers.add(o); }
    void transitionTo(OrderStatus next) {
        if (!status.canGoTo(next)) throw new IllegalStateException(status + " cannot go to " + next);
        status = next;
        log.info(() -> id + " → " + next);
        observers.forEach(o -> o.onStatusChange(this)); // Observer notifies all
    }
}

class OrderService {
    Order place(String user, String restaurant, List<MenuItem> items) {
        Order o = new Order("ORD-1", user, restaurant);
        o.items.addAll(items);
        return o;
    }
}

public class FoodDemo {
    public static void main(String[] args) {
        OrderService svc = new OrderService();
        Order order = svc.place("Rajesh", "Spice Hub",
                List.of(new MenuItem("Biryani", new BigDecimal("250"))));
        order.subscribe(o -> Logger.getLogger("USER").info("Rajesh notified: " + o.status));
        order.subscribe(o -> Logger.getLogger("REST").info("Spice Hub sees: " + o.status));
        order.transitionTo(OrderStatus.ACCEPTED);
        order.transitionTo(OrderStatus.PREPARING);
        order.transitionTo(OrderStatus.OUT_FOR_DELIVERY);
        order.transitionTo(OrderStatus.DELIVERED);
    }
}
